insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('med-words','doctor-pharmacy','words','U lekarza','Симптомы и консультация','8 карточек · A2','Опиши состояние и пойми основные вопросы',8,'🩺','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}',73,true),('med-grammar','doctor-pharmacy','grammar','Trzeba czy powinien?','Рекомендации и запреты','5 заданий · A2','Используй trzeba, należy, powinien и nie wolno',9,'✏️','Trzeba, należy, powinien, nie wolno','[["Общая необходимость","Trzeba + инфинитив: trzeba odpoczywać."],["Рекомендация","Powinien/powinna/powinno согласуется с человеком; официальное należy остаётся безличным."],["Запрет","Nie wolno + инфинитив: nie wolno przekraczać dawki."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}',74,true),('med-review','doctor-pharmacy','review','W aptece','Безопасный приём лекарств','7 карточек · A2','Повтори дозировку и важные предупреждения',7,'🔄','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}',75,true),('med-quiz','doctor-pharmacy','quiz','Quiz: lekarz i apteka','Проверка темы','8 вопросов · A2','Проверь лексику и конструкции рекомендации',6,'🎯','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}',76,true),('med-reading-check','doctor-pharmacy','quiz','Czy rozumiesz zalecenia?','Понимание текста','5 вопросов · A2','Проверь детали консультации Адама',5,'📖','','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}',77,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.flashcards(id,polish,translation,example,position,is_active,source_metadata) values ('med-objaw','objaw','симптом','Proszę dokładnie opisać objawy.',256,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-kaszel','kaszel','кашель','Mam suchy kaszel od trzech dni.',257,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-goraczka','gorączka','высокая температура','Wieczorem miałem wysoką gorączkę.',258,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-bol-gardla','ból gardła','боль в горле','Ból gardła jest dziś silniejszy.',259,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-recepta','recepta','рецепт','Lekarz wystawił receptę elektroniczną.',260,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-dawkowanie','dawkowanie','дозировка','Dawkowanie jest napisane na opakowaniu.',261,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-tabletka','tabletka','таблетка','Proszę brać jedną tabletkę rano.',262,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-syrop','syrop','сироп','Ten syrop pomaga na kaszel.',263,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-badanie','badanie','обследование','Lekarz skierował mnie na badanie krwi.',264,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-uczulenie','uczulenie','аллергия','Czy ma pan uczulenie na antybiotyki?',265,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-skutek','skutek uboczny','побочный эффект','Senność może być skutkiem ubocznym.',266,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-przyjmowac','przyjmować lek','принимать лекарство','Lek trzeba przyjmować po jedzeniu.',267,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-pogorszyc','pogorszyć się','ухудшиться','Jeśli stan się pogorszy, proszę zadzwonić.',268,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-poprawic','poprawić się','улучшиться','Po dwóch dniach powinno się poprawić.',269,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('med-zwolnienie','zwolnienie lekarskie','больничный лист','Dostałam zwolnienie lekarskie na trzy dni.',270,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('adam-u-lekarza-i-w-aptece','doctor-pharmacy','Adam u lekarza i w aptece','Консультация, рекомендации и безопасный приём лекарства','A2',6,'💊','["Adam od trzech dni miał suchy kaszel, ból gardła i osłabienie. Wieczorem temperatura wzrosła do trzydziestu ośmiu stopni, dlatego rano umówił wizytę u lekarza. Podczas konsultacji dokładnie opisał objawy i powiedział, że nie ma uczulenia na leki.","Lekarz zbadał gardło i płuca. Wyjaśnił, że prawdopodobnie jest to infekcja wirusowa, więc antybiotyk nie jest potrzebny. Adam powinien odpoczywać, dużo pić i przyjmować lek przeciwgorączkowy tylko zgodnie z dawkowaniem. Dostał też zwolnienie lekarskie na trzy dni.","W aptece farmaceutka sprawdziła receptę i zapytała, czy Adam przyjmuje inne leki. Wyjaśniła, że tabletki należy brać po jedzeniu i nie wolno przekraczać zalecanej dawki. Jeśli stan Adama się pogorszy albo gorączka nie minie, powinien ponownie skontaktować się z lekarzem."]','{"osłabienie":{"lemma":"osłabienie","translation":"слабость","part_of_speech":"существительное"},"wzrosła":{"lemma":"wzrosnąć","translation":"повыситься","part_of_speech":"глагол"},"umówił":{"lemma":"umówić","translation":"назначить; договориться","part_of_speech":"глагол"},"zbadał":{"lemma":"zbadać","translation":"осмотреть","part_of_speech":"глагол"},"płuca":{"lemma":"płuco","translation":"лёгкие","part_of_speech":"существительное"},"wirusowa":{"lemma":"wirusowy","translation":"вирусный","part_of_speech":"прилагательное"},"przeciwgorączkowy":{"lemma":"przeciwgorączkowy","translation":"жаропонижающий","part_of_speech":"прилагательное"},"dawkowaniem":{"lemma":"dawkowanie","translation":"дозировка","part_of_speech":"существительное"},"przekraczać":{"lemma":"przekraczać","translation":"превышать","part_of_speech":"глагол"},"zalecanej":{"lemma":"zalecany","translation":"рекомендованный","part_of_speech":"прилагательное"},"pogorszy":{"lemma":"pogorszyć się","translation":"ухудшиться","part_of_speech":"глагол"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29","comprehension_lesson_id":"med-reading-check"}',17,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
