delete from public.lesson_flashcards where lesson_id in ('med-words','med-review'); insert into public.lesson_flashcards(lesson_id,flashcard_id,position) values ('med-words','med-objaw',0),('med-words','med-kaszel',1),('med-words','med-goraczka',2),('med-words','med-bol-gardla',3),('med-words','med-recepta',4),('med-words','med-dawkowanie',5),('med-words','med-tabletka',6),('med-words','med-syrop',7),('med-review','med-badanie',0),('med-review','med-uczulenie',1),('med-review','med-skutek',2),('med-review','med-przyjmowac',3),('med-review','med-pogorszyc',4),('med-review','med-poprawic',5),('med-review','med-zwolnienie',6);
delete from public.questions where lesson_id in ('med-grammar','med-quiz','med-reading-check'); insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('med-grammar','Przy gorączce ___ dużo pić.','["trzeba","wolno nie","powinienem jest"]',0,'Безличное trzeba + инфинитив выражает общую необходимость.',0),('med-grammar','Pan ___ odpoczywać przez dwa dni.','["powinien","powinna","powinni"]',0,'Форма powinien согласуется с pan в мужском роде.',1),('med-grammar','Kobieta w ciąży ___ skonsultować lek z lekarzem.','["powinna","powinien","powinno"]',0,'Для женщины: powinna + инфинитив.',2),('med-grammar','Здесь нельзя курить.','["Tutaj trzeba palić.","Tutaj nie wolno palić.","Tutaj powinien palić."]',1,'Запрет выражает безличное nie wolno + инфинитив.',3),('med-grammar','Lek ___ przyjmować po jedzeniu.','["należy","należą","należy się go"]',0,'В инструкции нейтральная рекомендация: należy + инфинитив.',4),('med-quiz','Что означает dawkowanie?','["диагноз","дозировка","приёмная"]',1,'Dawkowanie — количество и частота приёма лекарства.',0),('med-quiz','Przy bólu gardła ___ pić ciepłe napoje.','["warto","nie wolno zawsze","powinien są"]',0,'Warto + инфинитив даёт мягкую рекомендацию.',1),('med-quiz','Dziecko ___ zostać w domu.','["powinno","powinien","powinna"]',0,'Dziecko — средний род: powinno.',2),('med-quiz','Как сообщить об аллергии?','["Mam uczulenie na penicylinę.","Biorę receptę gorączką.","Objaw należy apteka."]',0,'Mam uczulenie na… — стандартная фраза об аллергии.',3),('med-quiz','Antybiotyku nie wolno ___ bez konsultacji.','["odstawiać","odstawiał","odstawienie"]',0,'После nie wolno нужен инфинитив: odstawiać.',4),('med-quiz','Если состояние ухудшится…','["Jeśli stan się pogorszy…","Kiedy recepta dawkowanie…","Gdy lek powinien był…"]',0,'Pogorszyć się — ухудшиться; jeśli вводит реальное условие.',5),('med-quiz','Что может вызвать сонливость?','["skutek uboczny leku","zwolnienie lekarskie","badanie gardła"]',0,'Сонливость может быть побочным эффектом лекарства.',6),('med-quiz','Lek ___ dwa razy dziennie.','["należy przyjmować","należy przyjmował","powinno przyjmują"]',0,'Безличная инструкция: należy przyjmować.',7),('med-reading-check','Jak długo Adam miał objawy?','["Od jednego wieczoru","Od trzech dni","Od dwóch tygodni"]',1,'Кашель и слабость продолжались три дня.',0),('med-reading-check','Dlaczego lekarz nie przepisał od razu antybiotyku?','["Objawy wskazywały na infekcję wirusową","Adam nie miał dokumentów","Apteka była zamknięta"]',0,'Врач счёл инфекцию вирусной, поэтому антибиотик не требовался.',1),('med-reading-check','Co lekarz zalecił Adamowi?','["Dużo odpoczynku i picia","Intensywny trening","Pracę w nocy"]',0,'Рекомендации: отдых, жидкость и средство от температуры.',2),('med-reading-check','O co farmaceutka zapytała Adama?','["O uczulenia i inne leki","O miejsce pracy","O rozmiar ubrania"]',0,'Фармацевт уточнила аллергию и другие лекарства.',3),('med-reading-check','Kiedy Adam ma ponownie skontaktować się z lekarzem?','["Gdy stan się pogorszy lub gorączka nie minie","Po każdej tabletce","Dopiero za rok"]',0,'Повторная консультация нужна при ухудшении или сохраняющейся температуре.',4);
